const elwynnQuestSelections = new WeakMap();
function questGearProfile(hero) {
  const cls=hero?.cls;
  if(!['warrior','paladin','hunter','rogue','druid','mage','priest','warlock'].includes(cls))return null;
  const spec=S.hero===hero?S.specs?.me:hero.specs?.me;
  const primary=B.primaryKey(cls,spec||B.CLASSES[cls].def);
  const armor=['warrior','paladin'].includes(cls)?'mail':['hunter','rogue','druid'].includes(cls)?'leather':'cloth';
  return armor+':'+primary;
}
function canEquipQuestGear(hero,item) {
  return !item.allowedClasses||item.allowedClasses.includes(hero?.cls);
}
function questGearOptions(hero,key) {
  const profile=questGearProfile(hero);
  if(!profile)return key==='kobold_camp'?gearItems.filter(item=>item.id===57001):[];
  return gearItems.filter(item=>item.questSource===key&&item.questProfile===profile&&canEquipQuestGear(hero,item));
}
function selectQuestGear(hero,key,id) {
  if(S.hero!==hero||qState(key)!==2||!questGearOptions(hero,key).some(item=>item.id===id))return false;
  let chosen=elwynnQuestSelections.get(hero);
  if(!chosen){chosen=new Map();elwynnQuestSelections.set(hero,chosen);}
  chosen.set(key,id);return true;
}
function resolveQuestGear(hero,key) {
  const options=questGearOptions(hero,key);
  if(!options.length)return null;
  if(options.length===1)return options[0];
  return options.find(item=>item.id===elwynnQuestSelections.get(hero)?.get(key))||false;
}
